<?php require __DIR__.'/includes/bootstrap.php';
$school=setting('school_name','Assistente do Curso Técnico');
function fetchRows($sql){try{return db()->query($sql)->fetchAll();}catch(Throwable $e){return [];}}
$events=fetchRows("SELECT * FROM events WHERE event_date IS NULL OR event_date>=NOW() ORDER BY event_date LIMIT 5");
$activities=fetchRows("SELECT a.title,a.due_date,s.name subject FROM activities a LEFT JOIN subjects s ON s.id=a.subject_id WHERE a.due_date IS NULL OR a.due_date>=CURRENT_DATE ORDER BY a.due_date LIMIT 6");
$materials=fetchRows("SELECT m.title,m.url,s.name subject FROM materials m LEFT JOIN subjects s ON s.id=m.subject_id ORDER BY m.id DESC LIMIT 6");
?>
<!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($school)?></title><link rel="stylesheet" href="<?=e(base_path('assets/style.css'))?>"></head><body><div class="main" style="max-width:1100px;margin:auto"><div class="hero"><span class="badge">Portal do Aluno</span><h1><?=e($school)?></h1><p>Consulte atividades, materiais, calendário e informações do Curso Técnico. Pelo WhatsApp, envie <strong>menu</strong> para iniciar.</p><a class="btn" style="background:#fff;color:#0f766e" href="<?=e(base_path('login.php'))?>">Painel administrativo</a></div><div class="menu-grid"><div class="public-card"><h2>📝 Atividades</h2><?php if(!$activities):?><p class="muted">Nenhuma atividade cadastrada.</p><?php endif;?><?php foreach($activities as $r):?><p><strong><?=e($r['title'])?></strong><br><span class="muted"><?=e($r['subject']??'')?><?=!empty($r['due_date'])?' • '.e(date('d/m/Y',strtotime($r['due_date']))):''?></span></p><?php endforeach;?></div><div class="public-card"><h2>📚 Materiais</h2><?php if(!$materials):?><p class="muted">Nenhum material cadastrado.</p><?php endif;?><?php foreach($materials as $r):?><p><strong><?=e($r['title'])?></strong><br><span class="muted"><?=e($r['subject']??'')?></span><?php if($r['url']):?><br><a href="<?=e($r['url'])?>" target="_blank" rel="noopener">Abrir material</a><?php endif;?></p><?php endforeach;?></div><div class="public-card"><h2>📅 Eventos</h2><?php if(!$events):?><p class="muted">Nenhum evento cadastrado.</p><?php endif;?><?php foreach($events as $r):?><p><strong><?=e($r['title'])?></strong><br><span class="muted"><?=!empty($r['event_date'])?e(date('d/m/Y H:i',strtotime($r['event_date']))):'Data a definir'?><?=!empty($r['location'])?' • '.e($r['location']):''?></span></p><?php endforeach;?></div></div></div></body></html>
